mapper.select:
SELECT customer_name AS name, COALESCE(SUM(total_amount), 0) AS value
FROM sales_order WHERE status = 3
GROUP BY customer_id, customer_name ORDER BY value DESC LIMIT #{top}

SELECT supplier_name AS name, COALESCE(SUM(total_amount), 0) AS value
FROM purchase_order WHERE status = 3
GROUP BY supplier_id, supplier_name ORDER BY value DESC LIMIT #{top}
